sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = {};
    try {
        if (request.body && request.body.dataString) {
            body = JSON.parse(request.body.dataString);
        } else if (request.body && request.body.data) {
            body = typeof request.body.data === 'string' ? JSON.parse(request.body.data) : request.body.data;
        }
    } catch (e) {
        response.setStatus(400);
        response.setBody({ result: { success: false, error: 'Invalid JSON request payload' } });
        return;
    }

    var gateway = new x_2056099_indust_0.IoTStreamingGateway();
    var result;

    if (body.action === 'simulate' || body.simulate === true) {
        result = gateway.simulateAllMachines();
    } else {
        result = gateway.ingest(body);
    }

    if (!result.success) {
        response.setStatus(400);
    }
    response.setBody({ result: result });
})(request, response);
